  "admin.categories.lock.childAssignmentError": { en: "{name} already has child categories and cannot be assigned under another category.", ar: "تحتوي {name} على فئات فرعية، لذلك لا يمكن تعيينها ضمن فئة أخرى.", ur: "{name} کے پاس پہلے سے چائلڈ زمرے ہیں اور اسے کسی اور زمرے کے تحت تفویض نہیں کیا جا سکتا۔" },
